// Scrape all available platforms for this referente
const body = $('Webhook').item.json.body || $('Webhook').item.json;
const { referente, apify_token, supabase_url, supabase_key, anthropic_key } = body;

console.log(`Starting scrape for referente: ${referente.name}`);

const allContent = [];

// ─── Instagram scrape ─────────────────────────────────────────
if (referente.ig_handle) {
  console.log(`Scraping Instagram: @${referente.ig_handle}`);
  try {
    const igResults = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.apify.com/v2/acts/apify~instagram-post-scraper/run-sync-get-dataset-items?token=${apify_token}&timeout=90`,
      body: {
        directUrls: [`https://www.instagram.com/${referente.ig_handle}/`],
        resultsType: 'posts',
        resultsLimit: 30
      },
      json: true,
      timeout: 120000
    });

    for (const post of (Array.isArray(igResults) ? igResults : [])) {
      const views = post.videoPlayCount || 0;
      const likes = post.likesCount || 0;
      const isVideo = post.type === 'Video';
      const isCarousel = post.type === 'Sidecar';

      // Filter: videos >= 50k views OR images/carousels >= 5k likes
      if ((isVideo && views >= 50000) || (!isVideo && likes >= 5000)) {
        allContent.push({
          referente_id: referente.id,
          platform: 'instagram',
          content_type: isVideo ? 'video' : (isCarousel ? 'carousel' : 'image'),
          source_type: 'organic',
          post_url: post.url || null,
          post_id: post.id ? `ig_${post.id}` : `ig_${Date.now()}_${Math.random().toString(36).slice(2)}`,
          posted_at: post.timestamp || null,
          views: views,
          likes: likes,
          comments: post.commentsCount || 0,
          shares: 0,
          original_caption: post.caption || '',
          media_url: post.videoUrl || post.displayUrl || null,
          thumbnail_url: post.displayUrl || null,
          is_used: false
        });
      }
    }
    console.log(`Instagram: ${allContent.filter(c => c.platform === 'instagram').length} posts passed filter`);
  } catch(e) {
    console.log('Instagram scrape error:', e.message);
  }
}

// ─── TikTok scrape ────────────────────────────────────────────
if (referente.tiktok_handle) {
  console.log(`Scraping TikTok: @${referente.tiktok_handle}`);
  try {
    const tkResults = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.apify.com/v2/acts/clockworks~free-tiktok-scraper/run-sync-get-dataset-items?token=${apify_token}&timeout=90`,
      body: {
        profiles: [referente.tiktok_handle],
        resultsPerPage: 30
      },
      json: true,
      timeout: 120000
    });

    for (const post of (Array.isArray(tkResults) ? tkResults : [])) {
      const views = post.playCount || post.stats?.playCount || 0;
      if (views >= 50000) {
        allContent.push({
          referente_id: referente.id,
          platform: 'tiktok',
          content_type: 'video',
          source_type: 'organic',
          post_url: post.webVideoUrl || null,
          post_id: post.id ? `tk_${post.id}` : `tk_${Date.now()}_${Math.random().toString(36).slice(2)}`,
          posted_at: post.createTimeISO || null,
          views: views,
          likes: post.diggCount || post.stats?.diggCount || 0,
          comments: post.commentCount || post.stats?.commentCount || 0,
          shares: post.shareCount || post.stats?.shareCount || 0,
          original_caption: post.text || '',
          media_url: post.videoMeta?.playAddr || null,
          thumbnail_url: post.videoMeta?.coverUrl || null,
          is_used: false
        });
      }
    }
    console.log(`TikTok: ${allContent.filter(c => c.platform === 'tiktok').length} posts passed filter`);
  } catch(e) {
    console.log('TikTok scrape error:', e.message);
  }
}

// ─── Facebook Ads Library scrape ──────────────────────────────
if (referente.fb_page_url) {
  console.log(`Scraping Facebook Ads: ${referente.fb_page_url}`);
  try {
    const fbResults = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.apify.com/v2/acts/apify~facebook-ads-library-scraper/run-sync-get-dataset-items?token=${apify_token}&timeout=90`,
      body: {
        adLibraryQuery: referente.fb_page_url,
        maxAds: 30,
        countryCode: 'ALL'
      },
      json: true,
      timeout: 120000
    });

    for (const ad of (Array.isArray(fbResults) ? fbResults : [])) {
      const daysActive = ad.daysActive || 0;
      if (daysActive >= 3) {
        allContent.push({
          referente_id: referente.id,
          platform: 'facebook_ads',
          content_type: ad.isVideo ? 'video' : 'image',
          source_type: 'paid',
          post_url: ad.adUrl || null,
          post_id: ad.adArchiveId ? `fb_${ad.adArchiveId}` : `fb_${Date.now()}_${Math.random().toString(36).slice(2)}`,
          posted_at: null,
          views: 0,
          likes: 0,
          comments: 0,
          shares: 0,
          days_active: daysActive,
          original_caption: ad.adText || ad.body || '',
          media_url: ad.videoUrl || ad.imageUrl || null,
          thumbnail_url: ad.imageUrl || null,
          is_used: false
        });
      }
    }
    console.log(`FB Ads: ${allContent.filter(c => c.platform === 'facebook_ads').length} ads passed filter`);
  } catch(e) {
    console.log('Facebook Ads scrape error:', e.message);
  }
}

console.log(`Total scraped: ${allContent.length} pieces for ${referente.name}`);
return [{ json: { allContent, referente, supabase_url, supabase_key, anthropic_key } }];

// Analyze each piece with Claude Sonnet and save to referente_content
const { allContent, referente, supabase_url, supabase_key, anthropic_key } = $input.first().json;

if (!allContent || allContent.length === 0) {
  console.log('No content to analyze for', referente.name);
  // Update referente status to reflect scraping was done
  const statusUpdate = {};
  if (referente.ig_handle) statusUpdate.ig_status = 'not_found';
  if (referente.tiktok_handle) statusUpdate.tiktok_status = 'not_found';
  if (Object.keys(statusUpdate).length > 0) {
    try {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: `${supabase_url}/rest/v1/referentes?id=eq.${referente.id}`,
        headers: { 'Authorization': `Bearer ${supabase_key}`, 'apikey': supabase_key, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: statusUpdate,
        json: true
      });
    } catch(e) { console.log('Status update error:', e.message); }
  }
  return [{ json: { done: true, saved: 0, total: 0, referente: referente.name } }];
}

let savedCount = 0;

for (const content of allContent) {
  let quality_score = 5;
  let strategic_analysis = null;
  let content_structure = null;

  // Analyze with Claude Sonnet
  try {
    const caption = (content.original_caption || '').substring(0, 800);
    const metrics = [
      content.views > 0 ? `Vistas: ${content.views.toLocaleString()}` : '',
      content.likes > 0 ? `Likes: ${content.likes.toLocaleString()}` : '',
      content.comments > 0 ? `Comentarios: ${content.comments.toLocaleString()}` : '',
      content.days_active > 0 ? `Días activo: ${content.days_active}` : ''
    ].filter(Boolean).join(' | ');

    const analysisRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: {
        'x-api-key': anthropic_key,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json'
      },
      body: {
        model: 'claude-sonnet-4-5-20250929',
        max_tokens: 500,
        system: 'Eres un experto en análisis estratégico de contenido publicitario y orgánico de redes sociales. Responde ÚNICAMENTE con JSON válido, sin backticks ni texto adicional.',
        messages: [{
          role: 'user',
          content: `Analiza este contenido de ${content.platform} (${content.content_type}, ${content.source_type}):\n\nTexto/Caption: ${caption || 'Sin caption'}\nMétricas: ${metrics || 'Sin métricas'}\n\nResponde SOLO con este JSON:\n{\n  "quality_score": 7,\n  "strategic_analysis": "Por qué funciona este contenido y qué elemento lo hace ganador (hook, estructura, CTA, prueba social, etc.).",\n  "content_structure": "Tipo de hook usado, estructura del cuerpo (problema-solución, contraste, demostración, etc.), tipo de CTA."\n}`
        }]
      },
      json: true,
      timeout: 30000
    });

    const text = analysisRes.content?.[0]?.text || '';
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      quality_score = Math.min(10, Math.max(1, parsed.quality_score || 5));
      strategic_analysis = parsed.strategic_analysis || null;
      content_structure = parsed.content_structure || null;
    }
  } catch(e) {
    console.log('Analysis error:', e.message);
  }

  // Upsert to referente_content (dedup by platform + post_id)
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${supabase_url}/rest/v1/referente_content`,
      headers: {
        'Authorization': `Bearer ${supabase_key}`,
        'apikey': supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates,return=minimal'
      },
      body: {
        ...content,
        quality_score,
        strategic_analysis,
        content_structure,
        analyzed_at: new Date().toISOString()
      },
      json: true
    });
    savedCount++;
  } catch(e) {
    console.log('Save error:', e.message);
  }
}

// Update referente scraping status
const statusUpdate = {};
const igSaved = allContent.filter(c => c.platform === 'instagram').length;
const tkSaved = allContent.filter(c => c.platform === 'tiktok').length;
if (referente.ig_handle) statusUpdate.ig_status = igSaved > 0 ? 'found' : 'not_found';
if (referente.tiktok_handle) statusUpdate.tiktok_status = tkSaved > 0 ? 'found' : 'not_found';

if (Object.keys(statusUpdate).length > 0) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${supabase_url}/rest/v1/referentes?id=eq.${referente.id}`,
      headers: { 'Authorization': `Bearer ${supabase_key}`, 'apikey': supabase_key, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: statusUpdate,
      json: true
    });
  } catch(e) { console.log('Status update error:', e.message); }
}

console.log(`Saved ${savedCount}/${allContent.length} pieces for ${referente.name}`);
return [{ json: { done: true, saved: savedCount, total: allContent.length, referente: referente.name } }];
